css:
.pow-att { font-size: 11px; }
.pow-hd { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.pow-logo { max-height: 60px; }
.pow-title { font-size: 20px; font-weight: bold; text-align: right; }
.pow-name { font-size: 11px; color: #555; text-align: right; }
.pow-meta { margin: 6px 0 14px; font-size: 11px; }
.pow-meta span { margin-right: 18px; }
.pow-att-tbl { width: 100%; border-collapse: collapse; table-layout: fixed; }
.pow-att-tbl th, .pow-att-tbl td { border: 1px solid #bbb; padding: 6px 8px; vertical-align: top; word-wrap: break-word; overflow-wrap: break-word; }
.pow-att-tbl thead { display: table-row-group; }
.pow-att-tbl thead th { background: #f2f2f2; text-align: left; font-weight: bold; }
.pow-att-tbl .c-sr { width: 4%; }
.pow-att-tbl .c-item { width: 15%; }
.pow-att-tbl .c-type { width: 11%; }
.pow-att-tbl .c-contract { width: 17%; }
.pow-att-tbl .c-actual { width: 9%; }
.pow-att-tbl .c-staff { width: 44%; }
.pow-att-tbl .ln { margin-bottom: 6px; line-height: 1.35; }
.pow-att-tbl .ln:last-child { margin-bottom: 0; }
.pow-att-tbl .or { font-weight: bold; margin: 6px 0; }
.pow-att-tbl td.empty { text-align: left; font-style: italic; color: #666; }
@media print { @page { size: A4 portrait; margin: 12mm; } }
